// Illustrative scene art lives in /public/images (generated by tools/media/gen_media.py).
// Replace with real project photos (AVIF/WebP, same file names) when the client supplies them (Blueprint 6.4).
const industryArt: Record<string, string> = {
  'apartments-and-gated-communities': 'ind-apartments', villas: 'ind-villas', 'it-parks': 'ind-it-parks', warehouses: 'ind-warehouses',
  hospitals: 'ind-hospitals', malls: 'ind-malls', schools: 'ind-schools', hotels: 'ind-hotels', factories: 'ind-factories',
  'cold-storage': 'ind-cold-storage', parking: 'ind-parking', showrooms: 'ind-showrooms', airports: 'ind-airports',
  'data-centres': 'ind-data-centres', government: 'ind-government',
}
export const categoryImage = (slug: string) => slug === 'garage-doors' ? '/images/garage-doors.webp' : slug === 'rfid-access-control' ? '/images/p-uhf-rfid-long-range-reader-azuhfr105a.webp' : `/images/${slug}.webp`
export const industryImage = (slug: string) => `/images/${industryArt[slug] ?? 'ind-default'}.webp`
const productArt: Record<string, string> = {
  'garage-doors/residential-garage-doors': '/images/p-residential-sectional-doors.webp',
  'garage-doors/insulated-garage-doors': '/images/p-garage-sectional-doors.webp',
  'garage-doors/full-vision-garage-doors': '/images/p-full-vision-glass-sectional-doors.webp',
  'garage-doors/wooden-finish-garage-doors': '/images/p-wooden-finish-sectional-doors.webp',
}
export const productImage = (category: string, slug?: string) => (slug ? (productArt[`${category}/${slug}`] ?? `/images/p-${slug}.webp`) : categoryImage(category))
export const SERVICE_IMAGE = '/images/service.webp'
// Every service page has its own hero: /images/svc-<service-slug>.webp (replace the file, same name, no code change).
// Only slugs that really have a file in public/images get their own hero; any other service falls back to the shared service image
// (a missing svc-<slug>.webp used to 404, e.g. spare-parts). Add the slug here when you add public/images/svc-<slug>.webp (+ -640 twin).
const SERVICE_ART = new Set(['automatic-gate-installation', 'automatic-gate-repair', 'amc', 'convert-manual-gate-to-automatic', 'smart-control', 'access-control', 'safety-devices'])
export const serviceImage = (slug: string) => (SERVICE_ART.has(slug) ? `/images/svc-${slug}.webp` : SERVICE_IMAGE)
// Repair page shows what we repair, one image each: gate, glass door, window.
export const repairShots = [
  { src: '/images/svc-repair-gate.webp', label: 'Sliding and swing gates' },
  { src: '/images/svc-repair-glass-door.webp', label: 'Automatic glass doors' },
  { src: '/images/svc-repair-window.webp', label: 'Automated windows' },
]
export const HERO_IMAGE = '/images/hero.webp'
export const HERO_POSTER = '/images/hero-poster.webp'
export const areaImage = (type: 'residential' | 'it' | 'industrial') =>
  type === 'it' ? '/images/ind-it-parks.webp' : type === 'industrial' ? '/images/ind-factories.webp' : '/images/g-gate-night.webp'

// Extra scenes shown in a product page gallery (besides the product's own image).
const related: Record<string, string[]> = {
  'gate-automation': ['g-gate-night', 'g-gate-day'], 'automatic-doors': ['g-lobby-night', 'ind-malls'], 'boom-barriers': ['g-barrier-dusk', 'ind-parking'], 'rfid-access-control': ['g-barrier-dusk', 'ind-parking'],
  'garage-doors': ['g-garage-dusk', 'p-residential-sectional-doors', 'p-wooden-finish-sectional-doors'], 'sectional-doors': ['p-industrial-sectional-doors', 'p-full-vision-glass-sectional-doors', 'p-garage-sectional-doors'], 'rolling-shutters': ['g-shutter-night', 'rolling-shutters'], 'high-speed-doors-dock': ['g-dock-day', 'g-factory-dusk'],
}
